parameters.command:
={{ (() => {
  const j = $json;
  const q = s => '"' + s + '"';
  const get = (...keys) => { for (const k of keys) { if (j[k] != null && String(j[k]).trim() !== '') return j[k]; } return ''; };
  const file = get('revit_file', 'Revit File Path');
  const conv = get('path_to_revit_converter', 'Path to Revit Converter (cli\\RVTconverter.exe)');
  const ddc = get('path_to_ddc', 'Path to ddc (command or full path)') || 'ddc';
  const outRaw = get('(optional) output_folder (must not exist yet)', 'Output folder (must not exist yet, default: <file>.converted)');
  const out = outRaw || file.replace(/\.(rvt|rfa)$/i, '') + '.converted';
  let opts = get('(optional) options', 'Options');
  if (Array.isArray(opts)) opts = opts.join(' ');
  if (!/--properties/.test(opts)) opts = ('--properties ' + opts).trim();
  const profile = get('(optional) IFC profile (full, coordination, geometry, custom)', 'IFC profile');
  const unit = get('(optional) IFC length unit (m, mm)', 'IFC length unit');
  const cats = get('(optional) only these categories (ids or English names)', 'Only these categories (ids or English names, e.g. -2000011,Doors)');
  const extra = (profile ? ' --ifc-profile ' + profile : '') + (unit ? ' --ifc-units ' + unit : '') + (cats ? ' --ifc-categories ' + q(cats) : '');
  const xlsx = file.replace(/\.(rvt|rfa)$/i, '') + '_rvt.xlsx';
  return q(conv) + ' ' + q(file) + ' -o ' + q(out) + ' ' + opts + extra + ' & ' + q(ddc) + ' table ' + q(out) + ' --xlsx ' + q(xlsx);
})() }}
